27	+/**
28	+ * A deck's roll press, arriving as a nonce.
29	+ *
30	+ * The press is the button, not the answer: the panel throws the dice the
31	+ * way "Roll for me" throws them, and the engine hears nothing until they
32	+ * have landed and been read. The flat tray's own timers carry the flight
33	+ * here, so the waiting is wound forward rather than waited out.
34	+ */
35	+
36	+const pack = {
37	+  vocabulary: {
38	+    unit: { one: "Stage", many: "Stages" },
39	+    subject: { one: "Piece", many: "Pieces" },
40	+    run: { one: "Firing", many: "Firings" },
41	+  },
42	+  tables: {},
43	+} as unknown as Pack;
44	+
45	+const state = { unit: 1, subjects: [], outcomes: [] } as unknown as RunState;
46	+
47	+const request: InputRequest = { kind: "roll", key: "u1:check#0", dice: "d6", label: "Roll the Kiln Check", purpose: "check" };
48	+
49	+/** The tray's flight for one die, and the beat the number is read for after it. */
50	+const FLIGHT_MS = 620 + 90;
51	+const READ_MS = 700;
52	+
53	+function renderPanel(machineRoll: number | undefined, onAnswer = vi.fn()) {
54	+  const view = render(
55	+    <RequestPanel request={request} pack={pack} state={state} onAnswer={onAnswer} onCancel={() => {}} machineRoll={machineRoll} />,
56	+  );
57	+  return {
58	+    onAnswer,
59	+    rerender: (n: number) =>
60	+      view.rerender(<RequestPanel request={request} pack={pack} state={state} onAnswer={onAnswer} onCancel={() => {}} machineRoll={n} />),
61	+  };
62	+}
63	+
64	+afterEach(() => {
65	+  cleanup();
66	+  vi.useRealTimers();
67	+});
68	+
69	+describe("a roll asked for from outside", () => {
70	+  it("throws the dice on the page and answers only once they have landed", async () => {
71	+    vi.useFakeTimers();
72	+    const { onAnswer, rerender } = renderPanel(0);
73	+    expect(document.querySelector(".tray")).toBeNull();
74	+
75	+    act(() => rerender(1));
76	+    // The dice are in the air: the tray is up, the total is held back, and
77	+    // the button says as much.
78	+    expect(document.querySelector(".tray")).toBeTruthy();
79	+    expect(screen.getByText("Rolling…")).toBeTruthy();
80	+    expect(onAnswer).not.toHaveBeenCalled();
81	+
82	+    await act(() => vi.advanceTimersByTimeAsync(FLIGHT_MS));
83	+    // Landed and shown, but not yet reported.
84	+    expect(onAnswer).not.toHaveBeenCalled();
85	+
86	+    await act(() => vi.advanceTimersByTimeAsync(READ_MS));
87	+    expect(onAnswer).toHaveBeenCalledTimes(1);
88	+    const [key, total, machineRolled, dice] = onAnswer.mock.calls[0]!;
89	+    expect(key).toBe("u1:check#0");
90	+    expect(total).toBeGreaterThanOrEqual(1);
91	+    expect(total).toBeLessThanOrEqual(6);
92	+    expect(machineRolled).toBe(true);
93	+    expect(dice).toHaveLength(1);
94	+  });
95	+
96	+  it("ignores a second press while the throw is still going", async () => {
97	+    vi.useFakeTimers();
98	+    const { onAnswer, rerender } = renderPanel(0);
99	+
100	+    act(() => rerender(1));
101	+    await act(() => vi.advanceTimersByTimeAsync(FLIGHT_MS));
102	+    const landed = document.querySelector(".rollTotal .big")!.textContent;
103	+    expect(landed).not.toBe("…");
104	+
105	+    // A press that arrives while the dice are down but unreported is not a
106	+    // second throw: the number that landed stands and goes in as it is.
107	+    act(() => rerender(2));
108	+    expect(document.querySelector(".rollTotal .big")!.textContent).toBe(landed);
109	+
110	+    await act(() => vi.advanceTimersByTimeAsync(READ_MS));
111	+    expect(onAnswer).toHaveBeenCalledTimes(1);
112	+    expect(onAnswer.mock.calls[0]![1]).toBe(Number(landed));
113	+  });
114	+
115	+  it("stays where it is until something presses it", () => {
116	+    vi.useFakeTimers();
117	+    const { onAnswer } = renderPanel(undefined);
118	+    expect(document.querySelector(".tray")).toBeNull();
119	+    expect(onAnswer).not.toHaveBeenCalled();
120	+  });
121	+});
